mapper.select:
SELECT t.txn_id, t.user_id, t.category_id, c.name AS category_name, t.merchant_name, t.amount, t.txn_date, t.txn_type FROM transaction t LEFT JOIN category c ON t.category_id = c.category_id WHERE t.user_id = #{userId} AND t.txn_type = 0 AND DATE_FORMAT(t.txn_date, '%Y-%m') = #{yearMonth}
AND t.category_id = #{categoryId}
ORDER BY t.txn_date DESC, t.created_at DESC
